		ADDTRI(6, 5, 4);

		//Top face
		ADDTRI(4, 5, 3);
		ADDTRI(3, 2, 4);

		//bottom face
		ADDTRI(1, 7, 6);
		ADDTRI(6, 0, 1);

		//left face
		ADDTRI(0, 6, 4);
		ADDTRI(4, 2, 0);

		//right face
		ADDTRI(5, 7, 1);
		ADDTRI(1, 3, 5);
#undef ADDTRI

		for (unsigned int i = 0; i < ind.size() / 3; i++)
