{
	PROFILE_SCOPED()

	if (m_needStaticGeomRebuild) {
		std::vector<AABBd> staticAabbs;

		m_enabledStaticGeoms = SortEnabledGeoms(m_staticGeoms);
		RebuildBVHTree(m_staticObjectTree.get(), m_enabledStaticGeoms, m_staticGeoms, staticAabbs);
